//! One residual per constraint kind: a function of the points and radii that is zero exactly when
//! the constraint holds (chapter 15.3). Each is written once, over dual numbers, so its
//! derivatives are generated by forward-mode differentiation and never typed by hand (chapter
//! 15.4).
//!
//! Every residual is a length in the block's scaled units, so one tolerance serves them all:
//! direction residuals are divided by a characteristic length of their lines, a power of two
//! fixed at the start; a distance uses (|PQ|^2 - d^2) / 2d, a polynomial whose gradient has length
//! one at the solution. Only `+`, `-`, `*`, `/` and `sqrt` are used, all exactly rounded IEEE
//! operations, so the values are the same bits on every machine.
//!
//! Circles and arcs (chapter 15.2): a radius is a variable, scaled as a length. A point on a
//! circle is |PC| - r, whose gradient has length one in the point; it is singular only at the
//! centre, which a sketch drawn so is refused before any derivative is taken (15.4's singular
//! set). Tangency has two forms. Anywhere, it is a distance: the centre's signed distance from
//! the line less the radius, or the centres' distance less the radii's sum or difference. Where
//! the two curves share a point, that distance form and the point's own place on both curves meet
//! in a double root, which takes a freedom from the rank that the geometry does not lose (the
//! point could slide along the tangent to first order). So at a shared point the residual is the
//! direction instead: the line is square to the radius there, or the shared point is in line with
//! both centres. Both forms are zero exactly when the curves touch there.

use crate::sketch::ConstraintId;
use crate::sketch::CurveId;
use num_dual::{Dual64, DualNum};

/// A constraint prepared for the solver: point and curve indices in authoring order and
/// constants in the block's scaled units.
#[derive(Clone, Copy, Debug)]
pub(super) enum Kind {
    /// Two equations: the x and y differences.
    Coincident { p: usize, q: usize },
    /// The y difference of a line's ends.
    Horizontal { p: usize, q: usize },
    /// The x difference of a line's ends.
    Vertical { p: usize, q: usize },
    /// The cross product of the two directions over a characteristic length.
    Parallel {
        a: [usize; 2],
        b: [usize; 2],
        inv_len: f64,
    },
    /// The dot product of the two directions over a characteristic length.
    Perpendicular {
        a: [usize; 2],
        b: [usize; 2],
        inv_len: f64,
    },
    /// The difference of the squared lengths over twice a characteristic length.
    EqualLength {
        a: [usize; 2],
        b: [usize; 2],
        inv_two_len: f64,
    },
    /// (|PQ|^2 - d^2) / 2d.
    Distance {
        p: usize,
        q: usize,
        d_squared: f64,
        inv_two_d: f64,
    },
    /// The signed distance from the line's carrier, less the stated signed distance.
    PointLine {
        p: usize,
        line: [usize; 2],
        signed: f64,
    },
    /// |PC| - r: a point on a curve's circle (an arc's own ends, or a point-on-curve).
    OnCircle {
        p: usize,
        centre: usize,
        curve: usize,
    },
    /// The centre's signed distance from the line's carrier, less the radius on the stated side
    /// (`sign` is 1 for the left, -1 for the right).
    LineTangent {
        line: [usize; 2],
        centre: usize,
        curve: usize,
        sign: f64,
    },
    /// At a shared point `at`: the line's direction dotted with the radius there, over a
    /// characteristic length of the line.
    LineTangentAt {
        line: [usize; 2],
        at: usize,
        centre: usize,
        inv_len: f64,
    },
    /// The centres' distance less `sign_a` ra + `sign_b` rb: (1, 1) outside, (-1, 1) the first
    /// inside the second, (1, -1) the second inside the first.
    CurvesTangent {
        centres: [usize; 2],
        curves: [usize; 2],
        sign_a: f64,
        sign_b: f64,
    },
    /// At a shared point `at`: the cross product of the two radii there, over a characteristic
    /// length of the centres' distance.
    CurvesTangentAt {
        centres: [usize; 2],
        at: usize,
        inv_len: f64,
    },
    /// r less a stated radius.
    RadiusIs { curve: usize, value: f64 },
    /// ra - rb.
    EqualRadius { a: usize, b: usize },
}

/// Who an equation belongs to: a constraint, or an arc's own ends staying on its circle.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Owner {
    /// A constraint the author added.
    Constraint(ConstraintId),
    /// An arc: its start and end lie on its circle.
    Arc(CurveId),
}

impl Owner {
    /// The constraint, if it is one.
    pub(super) fn constraint(self) -> Option<ConstraintId> {
        match self {
            Owner::Constraint(id) => Some(id),
            Owner::Arc(_) => None,
        }
    }
}

/// A prepared constraint.
#[derive(Clone, Copy, Debug)]
pub(super) struct Row {
    /// Whose equations they are.
    pub owner: Owner,
    /// What it says.
    pub kind: Kind,
}

/// A residual's equations: one, or two for a coincidence.
pub(super) struct Equations {
    pub first: Dual64,
    pub second: Option<Dual64>,
}

/// Each item once, in first-mention order.
fn once(all: Vec<usize>) -> Vec<usize> {
    let mut once = Vec::with_capacity(all.len());
    for item in all {
        if !once.contains(&item) {
            once.push(item);
        }
    }
    once
}

impl Kind {
    /// How many equations it adds.
    pub(super) fn equations(&self) -> usize {
        match self {
            Kind::Coincident { .. } => 2,
            _ => 1,
        }
    }

    /// The points it reads, in first-mention order, each once.
    pub(super) fn points(&self) -> Vec<usize> {
        once(match *self {
            Kind::Coincident { p, q } | Kind::Horizontal { p, q } | Kind::Vertical { p, q } => {
                vec![p, q]
            }
            Kind::Distance { p, q, .. } => vec![p, q],
            Kind::Parallel { a, b, .. }
            | Kind::Perpendicular { a, b, .. }
            | Kind::EqualLength { a, b, .. } => vec![a[0], a[1], b[0], b[1]],
            Kind::PointLine { p, line, .. } => vec![p, line[0], line[1]],
            Kind::OnCircle { p, centre, .. } => vec![p, centre],
            Kind::LineTangent { line, centre, .. } => vec![line[0], line[1], centre],
            Kind::LineTangentAt {
                line, at, centre, ..
            } => vec![line[0], line[1], at, centre],
            Kind::CurvesTangent { centres, .. } => vec![centres[0], centres[1]],
            Kind::CurvesTangentAt { centres, at, .. } => vec![centres[0], centres[1], at],
            Kind::RadiusIs { .. } | Kind::EqualRadius { .. } => Vec::new(),
        })
    }

    /// The curves whose radius it reads, in first-mention order, each once.
    pub(super) fn curves(&self) -> Vec<usize> {
        once(match *self {
            Kind::OnCircle { curve, .. }
            | Kind::LineTangent { curve, .. }
            | Kind::RadiusIs { curve, .. } => vec![curve],
            Kind::CurvesTangent { curves, .. } => vec![curves[0], curves[1]],
            Kind::EqualRadius { a, b } => vec![a, b],
            _ => Vec::new(),
        })
    }

    /// The residual at the positions `at` and the radii `radius` give, or `None` if one is
    /// missing.
    #[expect(
        clippy::arithmetic_side_effects,
        reason = "dual-number arithmetic is IEEE floating point: it cannot overflow or panic"
    )]
    #[expect(
        clippy::too_many_lines,
        reason = "one arm per residual, side by side so each reads in one place"
    )]
    pub(super) fn eval(
        &self,
        at: &impl Fn(usize) -> Option<(Dual64, Dual64)>,
        radius: &impl Fn(usize) -> Option<Dual64>,
    ) -> Option<Equations> {
        let direction = |line: [usize; 2]| -> Option<(Dual64, Dual64)> {
            let (x0, y0) = at(line[0])?;
            let (x1, y1) = at(line[1])?;
            Some((x1 - x0, y1 - y0))
        };
        let from = |p: usize, q: usize| -> Option<(Dual64, Dual64)> {
            let (px, py) = at(p)?;
            let (qx, qy) = at(q)?;
            Some((qx - px, qy - py))
        };
        let one = |value: Dual64| {
            Some(Equations {
                first: value,
                second: None,
            })
        };
        match *self {
            Kind::Coincident { p, q } => {
                let (px, py) = at(p)?;
                let (qx, qy) = at(q)?;
                Some(Equations {
                    first: px - qx,
                    second: Some(py - qy),
                })
            }
            Kind::Horizontal { p, q } => one(at(p)?.1 - at(q)?.1),
            Kind::Vertical { p, q } => one(at(p)?.0 - at(q)?.0),
            Kind::Parallel { a, b, inv_len } => {
                let (ax, ay) = direction(a)?;
                let (bx, by) = direction(b)?;
                one((ax * by - ay * bx) * inv_len)
            }
            Kind::Perpendicular { a, b, inv_len } => {
                let (ax, ay) = direction(a)?;
                let (bx, by) = direction(b)?;
                one((ax * bx + ay * by) * inv_len)
            }
            Kind::EqualLength { a, b, inv_two_len } => {
                let (ax, ay) = direction(a)?;
                let (bx, by) = direction(b)?;
                one(((ax * ax + ay * ay) - (bx * bx + by * by)) * inv_two_len)
            }
            Kind::Distance {
                p,
                q,
                d_squared,
                inv_two_d,
            } => {
                let (px, py) = at(p)?;
                let (qx, qy) = at(q)?;
                let (dx, dy) = (px - qx, py - qy);
                one((dx * dx + dy * dy - d_squared) * inv_two_d)
            }
            Kind::PointLine { p, line, signed } => {
                let (ux, uy) = direction(line)?;
                let (px, py) = at(p)?;
                let (ox, oy) = at(line[0])?;
                let (vx, vy) = (px - ox, py - oy);
                let length = (ux * ux + uy * uy).sqrt();
                one((ux * vy - uy * vx) / length - signed)
            }
            Kind::OnCircle { p, centre, curve } => {
                let (dx, dy) = from(centre, p)?;
                one((dx * dx + dy * dy).sqrt() - radius(curve)?)
            }
            Kind::LineTangent {
                line,
                centre,
                curve,
                sign,
            } => {
                let (ux, uy) = direction(line)?;
                let (vx, vy) = from(line[0], centre)?;
                let length = (ux * ux + uy * uy).sqrt();
                one((ux * vy - uy * vx) / length - radius(curve)? * sign)
            }
            Kind::LineTangentAt {
                line,
                at: shared,
                centre,
                inv_len,
            } => {
                let (ux, uy) = direction(line)?;
                let (rx, ry) = from(centre, shared)?;
                one((ux * rx + uy * ry) * inv_len)
            }
            Kind::CurvesTangent {
                centres,
                curves,
                sign_a,
                sign_b,
            } => {
                let (dx, dy) = from(centres[0], centres[1])?;
                let gap = (dx * dx + dy * dy).sqrt();
                one(gap - (radius(curves[0])? * sign_a + radius(curves[1])? * sign_b))
            }
            Kind::CurvesTangentAt {
                centres,
                at: shared,
                inv_len,
            } => {
                let (ax, ay) = from(shared, centres[0])?;
                let (bx, by) = from(shared, centres[1])?;
                one((ax * by - ay * bx) * inv_len)
            }
            Kind::RadiusIs { curve, value } => one(radius(curve)? - value),
            Kind::EqualRadius { a, b } => one(radius(a)? - radius(b)?),
        }
    }
}
